window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2d7820523b2aa5fc"]={"versions": [{"id": "FIG-2d7820523b2aa5fc", "releases": ["R1.5.1", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Hardware- und Netzwerk-Architekturdiagramm für das Zeitsynchronisations-Setup einer Time Aware Bridge (GTM/Bridge) gemäß AUTOSAR-Spezifikation des Time Synchronization Protocols (PRS_TimeSyncProtocol). Das Diagramm stellt die Topologie einer Bridge-Einheit dar, bei der der Global Time Master (GTM) als Management-CPU direkt an einen integrierten Ethernet-Switch angebunden ist und mehrere nachgelagerte TimeSlaves über Ethernet-Verbindungen synchronisiert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>GTM/Bridge</strong>: Übergeordneter Knoten bzw. Gesamtsystem, bestehend aus:</li>\n<li><strong>Management CPU</strong>: Host-Controller/Prozessor der Bridge, der die Time-Master-Funktion ausführt.</li>\n<li><strong>Switch</strong>: Netzwerk-Switch-Komponente mit nummerierten Ports <code>1</code>, <code>2</code>, <code>3</code>, <code>4</code> sowie weiteren generischen Ports (<code>...</code>).</li>\n<li><strong>Schnittstellen intern (GTM/Bridge)</strong>:</li>\n<li><strong>MII</strong>: Media Independent Interface zur Ethernet-Datenkommunikation zwischen Management CPU und Port <code>1</code> des Switches.</li>\n<li><strong>SPI</strong>: Serial Peripheral Interface zur Steuerung/Konfiguration des Switch-Bausteins durch die Management CPU.</li>\n<li><strong>TimeSlave</strong>: Drei dargestellte externe Netzknoten (Zeitempfänger), jeweils über eine Punkt-zu-Punkt-Verbindung (<strong>ETH</strong>) angebunden:</li>\n<li>TimeSlave 1 an Port <code>2</code></li>\n<li>TimeSlave 2 an Port <code>3</code></li>\n<li>TimeSlave 3 an Port <code>4</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Topologiedarstellung ohne explizite zeitliche Nachrichtenabfolgen. Die Management-CPU agiert als interner Master, speist Zeitsynchronisationsnachrichten (Sync, Follow_Up) über die MII-Schnittstelle in Port 1 des Switches ein, von wo aus die Weiterleitung über Switch-Hardware-Forwarding bzw. Switch-Ports (2, 3, 4) über die physikalischen Ethernet-Links (ETH) an die jeweiligen TimeSlaves erfolgt. Die Konfiguration und Registerverwaltung des Switches erfolgt über die SPI-Schnittstelle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert die Systemarchitektur für den Anwendungsfall [PRS_TS_00054] / RS_TS_20048 / RS_TS_20059. Für Entwickler und Systemarchitekten ist wesentlich, dass die Management-CPU über MII als Netzknoten am Switch (Port 1) hängt und zeitgleich über SPI Steuerzugriff auf den Switch besitzt. Die Zeitstempelung und Synchronisation nachgelagerter Slaves erfordert die switch-interne Erfassung von Sende- und Empfangszeitstempeln an den Ports 2 bis 4.</p>"}, {"id": "FIG-50e75484a87ee98f", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Ethernet-Zeitsynchronisation (PTP / IEEE 802.1AS) innerhalb der AUTOSAR PRS TimeSyncProtocol-Spezifikation. Dargestellt ist der Protokollablauf zwischen den Kommunikationspartnern GTM/Bridge (Port 1 - Port 3) und TimeSlave zur Taktsynchronisation und Peer-Delay-Messung (Laufzeitermittlung).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Lebenslinien/Rollen</strong>:</li>\n<li><code>GTM/Bridge</code> (Port 1 - Port 3) mit Uhrensymbol (Master-Referenzuhr)</li>\n<li><code>TimeSlave</code> mit Uhrensymbol (Slave-Uhr)</li>\n<li><strong>Nachrichten</strong>:</li>\n<li><code>Sync()</code></li>\n<li><code>Follow_Up(preciseOriginTimeStamp, T3-T2)</code></li>\n<li><code>Pdelay_Req()</code></li>\n<li><code>Pdelay_Resp(T4)</code></li>\n<li><code>Pdelay_Resp_Follow_Up(T3)</code></li>\n<li><strong>Zeitstempel & Variablen</strong>:</li>\n<li>Am Master: <code>T0</code> (sec & nsec, Global Time), <code>T0diff</code> (nsec, transmission delay mit T0diff = T1 - T0), Egress-Timestamps <code>T1</code>, <code>T2</code>, <code>T3</code>, Ingress-Timestamp <code>T4</code></li>\n<li>Am Slave: Ingress-Timestamp <code>Tsync</code>, Egress-Timestamp <code>Tpreq</code>, Ingress-Timestamp <code>Tpres</code></li>\n<li><strong>Berechnungsformeln</strong>:</li>\n<li><code>preciseOriginTimeStamp = T0 | T0diff</code></li>\n<li><code>RateRatio_n = (T3_n - T3_0) / (Tpres_n - Tpres_0)</code></li>\n<li><code>Pdelay_n = ((Tpres_n - Tpreq_n) - (T3_n - T4_n)) / 2</code></li>\n<li><code>RateRatio_n = (GlobalTime_n - GlobalTime_0) / (Tsync_n - Tsync_0)</code></li>\n<li><code>GlobalTime_n = (preciseOriginTimeStamp_n + (T3_n - T2_n) + Pdelay_n)</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Synchronisationsphase</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>GTM ermittelt Global Time <code>T0</code> und Verzögerung <code>T0diff</code>.</li>\n<li>Bei Egress werden Zeitstempel <code>T1</code>, <code>T2</code>, <code>T3</code> erfasst.</li>\n<li>Senden der Nachricht <code>Sync()</code> vom Master an den Slave; der Slave erfasst den Ingress-Zeitstempel <code>Tsync</code>.</li>\n<li>Senden der Nachricht <code>Follow_Up(preciseOriginTimeStamp, T3-T2)</code> vom Master an den Slave.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Peer-Delay-Messphase (Pdelay)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der TimeSlave sendet <code>Pdelay_Req()</code> an die Bridge und erfasst <code>Tpreq</code>.</li>\n<li>Die Bridge empfängt die Anfrage bei <code>T4</code> und antwortet mit <code>Pdelay_Resp(T4)</code>.</li>\n<li>Der TimeSlave erfasst beim Empfang den Zeitstempel <code>Tpres</code>.</li>\n<li>Die Bridge sendet <code>Pdelay_Resp_Follow_Up(T3)</code> mit dem Sendezeitstempel <code>T3</code> der vorherigen Response.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Slave-Berechnung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Slave berechnet über die dokumentierten Formeln die <code>RateRatio</code>, den Link-Delay <code>Pdelay</code> und korrigiert seine lokale Zeit auf <code>GlobalTime</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das präzise Zusammenspiel von Sync/Follow_Up und Pdelay-Mechanismen für Time-Aware-Bridge-Szenarien. Entwickler von TimeSync-Treibern (z. B. EthTSyn) müssen sicherstellen, dass Hardware-Zeitstempel an den entsprechenden Ingress- und Egress-Punkten korrekt ausgelesen, in die Follow_Up-Payloads eingebettet und gemäß den spezifizierten Berechnungsformeln für Pdelay und RateRatio ausgewertet werden.</p>"}, {"id": "FIG-d61e8a2a2036a170", "releases": ["R19-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Hardware- und Netzwerk-Architekturdiagramm für das Zeitsynchronisations-Setup einer Time Aware Bridge (GTM/Bridge) gemäß AUTOSAR-Spezifikation des Time Synchronization Protocols (PRS_TimeSyncProtocol). Das Diagramm stellt die Topologie einer Bridge-Einheit dar, bei der der Global Time Master (GTM) als Management-CPU direkt an einen integrierten Ethernet-Switch angebunden ist und mehrere nachgelagerte TimeSlaves über Ethernet-Verbindungen synchronisiert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>GTM/Bridge</strong>: Übergeordneter Knoten bzw. Gesamtsystem, bestehend aus:</li>\n<li><strong>Management CPU</strong>: Host-Controller/Prozessor der Bridge, der die Time-Master-Funktion ausführt.</li>\n<li><strong>Switch</strong>: Netzwerk-Switch-Komponente mit nummerierten Ports <code>1</code>, <code>2</code>, <code>3</code>, <code>4</code> sowie weiteren generischen Ports (<code>...</code>).</li>\n<li><strong>Schnittstellen intern (GTM/Bridge)</strong>:</li>\n<li><strong>MII</strong>: Media Independent Interface zur Ethernet-Datenkommunikation zwischen Management CPU und Port <code>1</code> des Switches.</li>\n<li><strong>SPI</strong>: Serial Peripheral Interface zur Steuerung/Konfiguration des Switch-Bausteins durch die Management CPU.</li>\n<li><strong>TimeSlave</strong>: Drei dargestellte externe Netzknoten (Zeitempfänger), jeweils über eine Punkt-zu-Punkt-Verbindung (<strong>ETH</strong>) angebunden:</li>\n<li>TimeSlave 1 an Port <code>2</code></li>\n<li>TimeSlave 2 an Port <code>3</code></li>\n<li>TimeSlave 3 an Port <code>4</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Topologiedarstellung ohne explizite zeitliche Nachrichtenabfolgen. Die Management-CPU agiert als interner Master, speist Zeitsynchronisationsnachrichten (Sync, Follow_Up) über die MII-Schnittstelle in Port 1 des Switches ein, von wo aus die Weiterleitung über Switch-Hardware-Forwarding bzw. Switch-Ports (2, 3, 4) über die physikalischen Ethernet-Links (ETH) an die jeweiligen TimeSlaves erfolgt. Die Konfiguration und Registerverwaltung des Switches erfolgt über die SPI-Schnittstelle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert die Systemarchitektur für den Anwendungsfall [PRS_TS_00054] / RS_TS_20048 / RS_TS_20059. Für Entwickler und Systemarchitekten ist wesentlich, dass die Management-CPU über MII als Netzknoten am Switch (Port 1) hängt und zeitgleich über SPI Steuerzugriff auf den Switch besitzt. Die Zeitstempelung und Synchronisation nachgelagerter Slaves erfordert die switch-interne Erfassung von Sende- und Empfangszeitstempeln an den Ports 2 bis 4.</p>"}], "trans": [{"from": "FIG-2d7820523b2aa5fc", "to": "FIG-50e75484a87ee98f", "fr": "R1.5.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Kompletter Austausch des Diagramminhalts: Architektur-/Blockdiagramm einer Time Aware Bridge durch ein Sequenzdiagramm (UML Sequence Diagram) zur Zeitsynchronisation und Laufzeitmessung (Sync, Follow_Up, Pdelay_Req, Pdelay_Resp, Pdelay_Resp_Follow_Up) zwischen GTM/Bridge und TimeSlave ersetzt.</li>\n</ul>"}, {"from": "FIG-50e75484a87ee98f", "to": "FIG-2d7820523b2aa5fc", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Kompletter Rücktausch des Diagramminhalts: Sequenzdiagramm zur Zeitsynchronisation durch das Architektur-/Blockdiagramm der Time Aware Bridge mit GTM als Management-CPU (Management CPU, Switch-Ports 1 bis 4/..., TimeSlaves über ETH) ersetzt.</li>\n</ul>"}, {"from": "FIG-2d7820523b2aa5fc", "to": "FIG-d61e8a2a2036a170", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
